INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'harmonious', 'adj.', '/hɑːˈməʊniəs/', '和谐的;友好和睦的', 'The painting reveals the artist''s hope for a harmonious life.', '这幅画表达了画家对和谐生活的期望。', 'Art and Artists', 1, 0, 'senior', 'wordlist', 'required3', 'U2', 'a harmonious life', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'figure', 'n.', '/ˈfɪɡə(r)/', '(画中的)人物;形象;人士', 'Qi Baishi often placed a tiny figure in the corner of his painting.', '齐白石常在画作角落画一个小小的人物。', 'Art and Artists', 2, 0, 'senior', 'wordlist', 'required3', 'U2', 'a figure in a painting', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'expression', 'n.', '/ɪkˈspreʃn/', '表达;表现;神情', 'His works are rich in expression and feeling.', '他的作品富于表现力和情感。', 'Art and Artists', 3, 0, 'senior', 'wordlist', 'required3', 'U2', 'rich in expression', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'detail', 'n.', '/ˈdiːteɪl/', '细节;细微之处', 'The artist liked to focus on the finer details of each flower.', '这位艺术家喜欢专注于每朵花的细微之处。', 'Art and Artists', 4, 0, 'senior', 'wordlist', 'required3', 'U2', 'in detail', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'energetic', 'adj.', '/ˌenəˈdʒetɪk/', '充满活力的;精力充沛的', 'He painted with bright colours and energetic strokes.', '他用明亮的色彩和充满活力的笔触作画。', 'Art and Artists', 5, 0, 'senior', 'wordlist', 'required3', 'U2', 'energetic strokes', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'stroke', 'n.', '/strəʊk/', '笔触;一笔', 'A single bold stroke can bring a fish to life on paper.', '寥寥一笔就能让纸上的鱼栩栩如生。', 'Art and Artists', 6, 0, 'senior', 'wordlist', 'required3', 'U2', 'a brush stroke', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'manner', 'n.', '/ˈmænə(r)/', '方式;方法', 'He created his works in a fresh and lively manner.', '他以清新而生动的方式创作作品。', 'Art and Artists', 7, 0, 'senior', 'wordlist', 'required3', 'U2', 'in a fresh manner', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'trend', 'n.', '/trend/', '趋势;潮流;动向', 'His art reflected an international trend in modern painting.', '他的艺术反映了现代绘画的国际潮流。', 'Art and Artists', 8, 0, 'senior', 'wordlist', 'required3', 'U2', 'an international trend', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'typical', 'adj.', '/ˈtɪpɪkl/', '典型的;有代表性的', 'He expressed modern ideas in a typical Chinese way.', '他以典型的中国方式表达现代理念。', 'Art and Artists', 9, 0, 'senior', 'wordlist', 'required3', 'U2', 'a typical Chinese way', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'recognise', 'v.', '/ˈrekəɡnaɪz/', '认出;辨认;承认;赞赏', 'The world recognises Qi Baishi first as a great painter.', '世人首先把齐白石视为一位伟大的画家。', 'Art and Artists', 10, 0, 'senior', 'wordlist', 'required3', 'U2', 'recognise sb as', '美式拼 recognize;美音 /ˈrekəɡnaɪz/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'pursue', 'v.', '/pəˈsjuː/', '追求;致力于;从事', 'As he grew older, the artist said what he pursued was world peace.', '随着年纪增长,这位艺术家说他所追求的是世界和平。', 'Art and Artists', 11, 0, 'senior', 'wordlist', 'required3', 'U2', 'pursue world peace', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'award', 'v./n.', '/əˈwɔːd/', '授予;颁发;奖项', 'He was awarded the International Peace Prize in 1956.', '他于1956年被授予国际和平奖。', 'Art and Artists', 12, 0, 'senior', 'wordlist', 'required3', 'U2', 'be awarded a prize', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'council', 'n.', '/ˈkaʊnsl/', '委员会;理事会', 'The prize was given to him by a famous peace council.', '这个奖项是由一个著名的和平理事会颁给他的。', 'Art and Artists', 13, 0, 'senior', 'wordlist', 'required3', 'U2', 'the World Peace Council', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'extend', 'v.', '/ɪkˈstend/', '致以;给予;延伸', 'The singer extended his warm greetings to all the guests.', '这位歌手向所有来宾致以热情的问候。', 'Art and Artists', 14, 0, 'senior', 'wordlist', 'required3', 'U2', 'extend greetings', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'greeting', 'n.', '/ˈɡriːtɪŋ/', '问候;招呼;致意', 'He sent his warmest greetings to the members of the academy.', '他向学院的成员致以最热烈的问候。', 'Art and Artists', 15, 0, 'senior', 'wordlist', 'required3', 'U2', 'warm greetings', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'distinguished', 'adj.', '/dɪˈstɪŋɡwɪʃt/', '杰出的;卓越的;著名的', 'Many distinguished guests came to honour the great artist.', '许多杰出的来宾前来向这位伟大的艺术家致敬。', 'Art and Artists', 16, 0, 'senior', 'wordlist', 'required3', 'U2', 'distinguished guests', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'literature', 'n.', '/ˈlɪtrətʃə(r)/', '文学;文学作品', 'Bob Dylan won the Nobel Prize for Literature in 2016.', '鲍勃·迪伦于2016年获得诺贝尔文学奖。', 'Art and Artists', 17, 0, 'senior', 'wordlist', 'required3', 'U2', 'the Nobel Prize for Literature', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'literary', 'adj.', '/ˈlɪtrəri/', '文学的;文学上的', 'Shakespeare is one of the greatest literary figures in history.', '莎士比亚是历史上最伟大的文学人物之一。', 'Art and Artists', 18, 0, 'senior', 'wordlist', 'required3', 'U2', 'a literary figure', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'tone', 'n.', '/təʊn/', '语气;腔调;色调', 'Their works are often spoken of in respectful tones.', '人们常以充满敬意的语气谈论他们的作品。', 'Art and Artists', 19, 0, 'senior', 'wordlist', 'required3', 'U2', 'in respectful tones', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'slight', 'adj.', '/slaɪt/', '轻微的;略微的', 'He said he never had the slightest chance of winning such a prize.', '他说自己丝毫没有赢得这样一个奖项的机会。', 'Art and Artists', 20, 0, 'senior', 'wordlist', 'required3', 'U2', 'the slightest chance', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'stage', 'v./n.', '/steɪdʒ/', '上演;举办;阶段;舞台', 'The director wondered how the new play should be staged.', '导演在思考这部新剧该如何上演。', 'Art and Artists', 21, 0, 'senior', 'wordlist', 'required3', 'U2', 'stage a play', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'ordinary', 'adj.', '/ˈɔːdnri/', '普通的;平常的', 'Even great artists must deal with many ordinary matters.', '即使是伟大的艺术家也必须处理许多平常的事务。', 'Art and Artists', 22, 0, 'senior', 'wordlist', 'required3', 'U2', 'ordinary matters', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'bet', 'v.', '/bet/', '敢说;打赌', 'I bet the question "Is this art?" never crossed his mind.', '我敢说"这是艺术吗?"这个问题从未在他脑中出现过。', 'Art and Artists', 23, 0, 'senior', 'wordlist', 'required3', 'U2', 'I bet', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'audience', 'n.', '/ˈɔːdiəns/', '观众;听众', 'Playing concerts meant he was reaching a big audience.', '举办音乐会意味着他正在触及大量的听众。', 'Art and Artists', 24, 0, 'senior', 'wordlist', 'required3', 'U2', 'a big audience', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'dozen', 'n.', '/ˈdʌzn/', '许多;一打;十二个', 'He has made dozens of records over his long career.', '在漫长的职业生涯中,他录制了几十张唱片。', 'Art and Artists', 25, 0, 'senior', 'wordlist', 'required3', 'U2', 'dozens of records', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'grateful', 'adj.', '/ˈɡreɪtfl/', '感激的;感谢的', 'The artist said he was deeply grateful for the great honour.', '这位艺术家说他对这一巨大荣誉深表感激。', 'Art and Artists', 26, 0, 'senior', 'wordlist', 'required3', 'U2', 'grateful for', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'occupy', 'v.', '/ˈɒkjupaɪ/', '使忙于;占用(时间/空间)', 'Like Shakespeare, he is often occupied with both his songs and daily matters.', '和莎士比亚一样,他常常忙于创作歌曲和处理日常事务。', 'Art and Artists', 27, 0, 'senior', 'wordlist', 'required3', 'U2', 'be occupied with', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'studio', 'n.', '/ˈstjuːdiəʊ/', '录音室;工作室;演播室', 'He asked himself whether he was recording in the right studio.', '他问自己是否在合适的录音室里录音。', 'Art and Artists', 28, 0, 'senior', 'wordlist', 'required3', 'U2', 'in the studio', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'ultimately', 'adv.', '/ˈʌltɪmətli/', '最终;最后;归根结底', 'He thanked the academy for ultimately giving such a wonderful answer.', '他感谢学院最终给出了如此美妙的答案。', 'Art and Artists', 29, 0, 'senior', 'wordlist', 'required3', 'U2', 'ultimately', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'charge', 'n.', '/tʃɑːdʒ/', '主管;掌管;职责', 'The artist who was in charge of the show chose the best paintings.', '负责这场展览的艺术家挑选了最好的画作。', 'Art and Artists', 30, 0, 'senior', 'wordlist', 'required3', 'U2', 'in charge of', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'reveal', 'v.', '/rɪˈviːl/', '揭示;显示;透露', 'The painting reveals the artist''s love of nature and life.', '这幅画揭示了艺术家对自然和生命的热爱。', 'Art and Artists', 31, 0, 'senior', 'wordlist', 'required3', 'U2', 'reveal a hope', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'lively', 'adj.', '/ˈlaɪvli/', '生动的;活泼的;充满生气的', 'His paintings of shrimps look fresh and lively.', '他画的虾看起来清新而生动。', 'Art and Artists', 32, 0, 'senior', 'wordlist', 'required3', 'U2', 'fresh and lively', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'subject', 'n.', '/ˈsʌbdʒɪkt/', '(绘画/写作的)题材;主题;学科', 'Doves were a common subject in his later paintings.', '鸽子是他后期画作中常见的题材。', 'Art and Artists', 33, 0, 'senior', 'wordlist', 'required3', 'U2', 'a common subject', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'ink', 'n.', '/ɪŋk/', '墨水;墨汁', 'Using heavy ink, he created strong and simple shapes.', '他用浓墨创造出有力而简洁的形象。', 'Art and Artists', 34, 0, 'senior', 'wordlist', 'required3', 'U2', 'heavy ink', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'blank', 'adj.', '/blæŋk/', '空白的;空着的', 'He left some parts of the paper blank, planning to add flowers later.', '他把纸上一些地方留白,打算以后再添上花朵。', 'Art and Artists', 35, 0, 'senior', 'wordlist', 'required3', 'U2', 'leave a space blank', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'retire', 'v.', '/rɪˈtaɪə(r)/', '退休;退出(公共生活)', 'While many artists retire from public life when old, he took on more duties.', '许多艺术家年老时退出公共生活,他却承担了更多责任。', 'Art and Artists', 36, 0, 'senior', 'wordlist', 'required3', 'U2', 'retire from public life', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'responsibility', 'n.', '/rɪˌspɒnsəˈbɪləti/', '责任;职责', 'He actively took on more social responsibilities in his old age.', '晚年时他积极承担起更多的社会责任。', 'Art and Artists', 37, 0, 'senior', 'wordlist', 'required3', 'U2', 'take on responsibilities', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'convey', 'v.', '/kənˈveɪ/', '传达;表达;传递', 'A painter must decide what message to convey through colour and shape.', '画家必须决定通过色彩和形状传达什么信息。', 'Art and Artists', 38, 0, 'senior', 'wordlist', 'required3', 'U2', 'convey a message', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'appreciate', 'v.', '/əˈpriːʃieɪt/', '欣赏;领会;感激', 'It takes some knowledge to appreciate a work of art.', '欣赏一件艺术品需要一定的知识。', 'Art and Artists', 39, 0, 'senior', 'wordlist', 'required3', 'U2', 'appreciate a work of art', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'imagine', 'v.', '/ɪˈmædʒɪn/', '想象;设想', 'Winning the prize was something he could never have imagined.', '获得这个奖项是他从未能想象到的事。', 'Art and Artists', 40, 0, 'senior', 'wordlist', 'required3', 'U2', 'could never imagine', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'creativity', 'n.', '/ˌkriːeɪˈtɪvəti/', '创造力;创造性', 'For Van Gogh, night was often a time of creativity.', '对梵高来说,夜晚常常是创作的时刻。', 'Art and Artists', 41, 0, 'senior', 'wordlist', 'required3', 'U2', 'a time of creativity', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'inspiration', 'n.', '/ˌɪnspəˈreɪʃn/', '灵感;鼓舞;启发', 'His paintings became a great source of inspiration for songs and films.', '他的画作成为歌曲和电影的巨大灵感来源。', 'Art and Artists', 42, 0, 'senior', 'wordlist', 'required3', 'U2', 'a source of inspiration', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'feature', 'n./v.', '/ˈfiːtʃə(r)/', '特色;特征;以……为特色', 'Loving Vincent is the world''s first fully oil-painted feature film.', '《至爱梵高》是世界上第一部完全用油画绘成的故事片。', 'Art and Artists', 43, 0, 'senior', 'wordlist', 'required3', 'U2', 'a feature film', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'perform', 'v.', '/pəˈfɔːm/', '表演;演奏;表现', 'The young musician was nervous before performing on stage.', '这位年轻音乐家在上台表演前很紧张。', 'Art and Artists', 44, 0, 'senior', 'wordlist', 'required3', 'U2', 'perform on stage', NULL, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s3u2.01', '①不定式作宾语(want/decide/hope/plan/refuse/manage to do;疑问词+to do)', 'A2', 10, '上外版必修第三册 U2 — want/decide/hope/plan/refuse/manage/wish/agree/offer/learn 等动词后接 to do 作宾语;know/wonder/decide/learn 等后接「疑问词(how/what/where/whether)+ to do」作宾语。', 1, 'required3', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s3u2.02', '②不定式作宾语补足语(ask/tell/allow/encourage sb to do;使役 make/let/have sb do 不带 to)', 'A2', 10, '上外版必修第三册 U2 — ask/tell/want/allow/encourage/advise/expect/invite sb to do,补足语带 to;但使役动词 make/let/have 及感官动词 hear/watch/feel/see 后接 sb + do(不带 to)。', 2, 'required3', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s3u2.03', '③不定式作状语和定语(目的/结果状语 to do、so as to;the first/best to do、a way to do、sth to do)', 'A2', 10, '上外版必修第三册 U2 — to do / in order to / so as to 作目的状语,…only to do 作结果状语;序数词/形容词最高级 + to do、a way/chance/time to do、sth/something to do 作定语,修饰前面的名词。', 3, 'required3', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.01'), 'The young painter hopes ____ his works in a city gallery one day.', 'to show', 'showing', 'shows', 'showed', 'A', 'hope 后接 to do 作宾语,表示希望去做某事。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.01'), 'Qi Baishi decided ____ on the finer details while his eyesight was still good.', 'focusing', 'to focus', 'focus', 'focused', 'B', 'decide 后接 to do 作宾语。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.01'), 'The art student wants ____ how the masters mixed their colours.', 'learning', 'learns', 'to learn', 'learn', 'C', 'want 后接 to do 作宾语。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.01'), 'After many failures, Van Gogh refused ____ painting.', 'giving up', 'gives up', 'gave up', 'to give up', 'D', 'refuse 后接 to do 作宾语,表示拒绝做某事。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.01'), 'Bob Dylan planned ____ a record so that his songs could be heard on the radio.', 'to make', 'making', 'makes', 'made', 'A', 'plan 后接 to do 作宾语。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.01'), 'Although money was short, the artist managed ____ his exhibition on time.', 'holding', 'to hold', 'held', 'hold', 'B', 'manage 后接 to do 作宾语,表示设法做成某事。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.01'), 'Before the show, the curator wondered how ____ the paintings on the walls.', 'arranging', 'arranges', 'to arrange', 'arranged', 'C', 'wonder 后接「疑问词 how + to do」作宾语。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.01'), 'Many visitors do not know what ____ when they look at modern art.', 'feeling', 'feels', 'felt', 'to feel', 'D', 'know 后接「疑问词 what + to do」作宾语。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.01'), 'Have you ever wondered how ____ for a symphony performance?', 'to dress', 'dressing', 'dresses', 'dressed', 'A', 'wonder 后接「疑问词 how + to do」作宾语。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.01'), 'The beginner needs to decide where ____ to study calligraphy.', 'going', 'to go', 'goes', 'went', 'B', 'decide 后接「疑问词 where + to do」作宾语。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.01'), 'The two artists agreed ____ on a painting for the festival together.', 'working', 'works', 'to work', 'worked', 'C', 'agree 后接 to do 作宾语。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.01'), 'Our music teacher offered ____ us to the opera this weekend.', 'taking', 'takes', 'took', 'to take', 'D', 'offer 后接 to do 作宾语,表示主动提出做某事。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.01'), 'The old master wished ____ his hometown through his ink paintings.', 'to honour', 'honouring', 'honours', 'honoured', 'A', 'wish 后接 to do 作宾语。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.01'), 'When his eyesight was failing, Qi still chose ____ on with his art.', 'carrying', 'to carry', 'carries', 'carried', 'B', 'choose 后接 to do 作宾语。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.01'), 'The young singer is still learning how ____ a large audience.', 'facing', 'faces', 'to face', 'faced', 'C', 'learn 后接「疑问词 how + to do」作宾语。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.01'), 'Before the concert, Dylan could not decide which song ____ first.', 'playing', 'plays', 'played', 'to play', 'D', 'decide 后接「疑问词 which (song) + to do」作宾语。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.01'), 'After the festival, the students promised ____ another art club next term.', 'to start', 'starting', 'starts', 'started', 'A', 'promise 后接 to do 作宾语。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.01'), 'The painter expects ____ his new landscape before winter comes.', 'finishing', 'to finish', 'finishes', 'finished', 'B', 'expect 后接 to do 作宾语,此处无 sb,直接接 to do。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.01'), 'Some guests at the gallery were not sure whether ____ the artist for a photo.', 'asking', 'asks', 'to ask', 'asked', 'C', '「疑问词 whether + to do」作宾语,用于动词后(here: be sure 后)。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.01'), 'The committee hopes ____ the young artist with a special prize this year.', 'honouring', 'honours', 'honoured', 'to honour', 'D', 'hope 后接 to do 作宾语。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.02'), 'Our teacher advised us ____ the opera at least once this year.', 'to see', 'seeing', 'saw', 'sees', 'A', 'advise sb to do,不定式带 to 作宾语补足语。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.02'), 'At the theatre, the audience are required ____ quiet during the play.', 'keeping', 'to keep', 'keep', 'kept', 'B', 'require sb to do(被动:be required to do),补足语带 to。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.02'), 'Sam asked the two noisy men behind him ____ chatting.', 'stopping', 'stop', 'to stop', 'stopped', 'C', 'ask sb to do,补足语带 to。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.02'), 'The gallery does not allow visitors ____ the oil paintings.', 'touching', 'touch', 'touched', 'to touch', 'D', 'allow sb to do,补足语带 to。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.02'), 'His art teacher always encouraged him ____ his own style.', 'to develop', 'developing', 'develop', 'developed', 'A', 'encourage sb to do,补足语带 to。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.02'), 'Yesterday I heard the street singer ____ "Blowin'' in the Wind".', 'to sing', 'sing', 'sings', 'sung', 'B', '感官动词 hear sb do,补足语不带 to。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.02'), 'The bright colours of the painting made the whole room ____ warmer.', 'to feel', 'feeling', 'feel', 'felt', 'C', '使役动词 make sth do,补足语不带 to。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.02'), 'Please let the children ____ the clay with their own hands.', 'to shape', 'shaping', 'shaped', 'shape', 'D', '使役动词 let sb do,补足语不带 to。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.02'), 'The museum guide had us ____ in front of the most famous portrait.', 'wait', 'to wait', 'waiting', 'waited', 'A', '使役动词 have sb do,补足语不带 to。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.02'), 'We watched the old painter ____ a few simple lines into a lively fish.', 'to turn', 'turn', 'turns', 'turned', 'B', '感官动词 watch sb do,补足语不带 to。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.02'), 'The director told the actors ____ their lines more slowly on stage.', 'saying', 'say', 'to say', 'said', 'C', 'tell sb to do,补足语带 to。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.02'), 'Sam expected other people ____ the noisy men to be quiet.', 'telling', 'tell', 'told', 'to tell', 'D', 'expect sb to do,补足语带 to。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.02'), 'The art club invited a local painter ____ a short talk about colour.', 'to give', 'giving', 'give', 'gave', 'A', 'invite sb to do,补足语带 to。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.02'), 'Strong feelings in the music can make a quiet listener ____ aloud.', 'to cry', 'cry', 'crying', 'cried', 'B', '使役动词 make sb do,补足语不带 to。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.02'), 'The judges wanted every group ____ five clues about a famous artist.', 'preparing', 'prepare', 'to prepare', 'prepared', 'C', 'want sb to do,补足语带 to。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.02'), 'Soft background music can make the guests ____ more relaxed at the show.', 'to feel', 'feeling', 'felt', 'feel', 'D', '使役动词 make sb do,补足语不带 to。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.02'), 'The teacher let each student ____ one painting to introduce to the class.', 'choose', 'to choose', 'choosing', 'chose', 'A', '使役动词 let sb do,补足语不带 to。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.02'), 'The school festival expects the winners ____ their work in the main hall.', 'displaying', 'to display', 'display', 'displayed', 'B', 'expect sb to do,补足语带 to。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.02'), 'We saw the dancer slowly ____ across the empty stage.', 'to move', 'moves', 'move', 'moved', 'C', '感官动词 see sb do,补足语不带 to。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.02'), 'Her parents always encouraged her ____ her dream of becoming a painter.', 'following', 'follow', 'followed', 'to follow', 'D', 'encourage sb to do,补足语带 to。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.03'), 'Painters use a variety of brushes ____ different effects on the paper.', 'to create', 'creating', 'create', 'created', 'A', 'to do 作目的状语,表示「为了创造……」。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.03'), 'Qi left some spaces blank ____ to add flowers later.', 'such as', 'so as', 'as so', 'as if', 'B', 'so as to do 作目的状语,表示「以便……」。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.03'), 'Bob Dylan became the first songwriter ____ the Nobel Prize for Literature.', 'winning', 'won', 'to win', 'wins', 'C', '序数词 first 后用 to do 作定语,修饰 songwriter。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.03'), 'Every great artist needs a message ____ through colour and shape.', 'conveying', 'convey', 'conveyed', 'to convey', 'D', 'to do 作定语,修饰 message,表示「要传达的信息」。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.03'), 'The students need a quiet place ____ their sketches in peace.', 'to finish', 'finishing', 'finish', 'finished', 'A', 'to do 作定语,修饰 place,表示「用来完成……的地方」。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.03'), 'He worked hard all his life ____ his dream of world peace.', 'pursuing', 'to pursue', 'pursue', 'pursued', 'B', 'to do 作目的状语,表示「为了追求……」。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.03'), 'Do you have the skills ____ a painting on your own?', 'appreciating', 'appreciate', 'to appreciate', 'appreciated', 'C', 'to do 作定语,修饰 skills,表示「欣赏……的技能」。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.03'), 'She arrived early at the gallery ____ a good seat near the stage.', 'getting', 'get', 'got', 'to get', 'D', 'to do 作目的状语,表示「为了得到……」。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.03'), 'Van Gogh was probably the best painter ____ the beauty of a starry night.', 'to capture', 'capturing', 'captured', 'captures', 'A', '形容词最高级 best 后用 to do 作定语,修饰 painter。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.03'), 'Spend some time figuring out the clues ____ the painter''s true feelings.', 'understanding', 'to understand', 'understand', 'understood', 'B', 'to do 作目的状语,表示「为了理解……」。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.03'), 'Is there anything ____ before the art exhibition opens tomorrow?', 'preparing', 'prepare', 'to prepare', 'prepared', 'C', 'to do 作定语,修饰不定代词 anything。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.03'), 'He saved money for years, only ____ that the painting had already been sold.', 'finding', 'find', 'found', 'to find', 'D', 'only to do 作结果状语,表示出乎意料的结果。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.03'), 'One good way ____ a painting is to place it in its time and place.', 'to appreciate', 'appreciating', 'appreciate', 'appreciated', 'A', 'to do 作定语,修饰 way,表示「欣赏……的方法」。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.03'), 'The young artist travelled to Paris in order ____ the works of the masters.', 'studying', 'to study', 'study', 'studied', 'B', 'in order to do 作目的状语,表示「为了研究……」。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.03'), 'Qi Baishi was one of the first Chinese artists ____ insects in such fine detail.', 'painting', 'painted', 'to paint', 'paints', 'C', '序数词 first 后用 to do 作定语,修饰 artists。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.03'), 'Visitors lined up ____ the most famous painting in the museum.', 'seeing', 'see', 'saw', 'to see', 'D', 'to do 作目的状语,表示「为了看……」。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.03'), 'Now is the right time ____ your own art club at school.', 'to start', 'starting', 'start', 'started', 'A', 'to do 作定语,修饰 time,表示「该……的时候」。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.03'), 'The museum stays open late ____ more working people a chance to visit.', 'giving', 'to give', 'give', 'gave', 'B', 'to do 作目的状语,表示「为了给……」。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.03'), 'He climbed onto the stage ____ the prize in person.', 'receiving', 'receive', 'to receive', 'received', 'C', 'to do 作目的状语,表示「为了亲自领奖」。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U2' AND code='s3u2.03'), 'I''m looking for a fresh subject ____ in my next ink painting.', 'painting', 'paint', 'painted', 'to paint', 'D', 'to do 作定语,修饰 subject,表示「要画的题材」。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Qi Baishi, the People''s Artist', 'Qi Baishi is one of the best-known Chinese painters of the twentieth century. Whether he painted landscapes, birds, flowers or small figures, his works are full of feeling and fine detail. Using heavy ink, bright colours and energetic strokes, he created pictures in a fresh and lively manner that expressed his deep love of nature and life. Although the world knows him first as a painter, he is also famous for his seal carvings and his poems. The man stayed hardworking even in his seventies. In one group of paintings he drew insects in the corners and left some spaces blank, because he wanted to finish the tiny details while his eyesight was still sharp, and planned to add flowers later. As he grew older, he set higher goals for himself. While many artists retire from public life when they are old, Qi took on more social duties instead. He once said that what he truly pursued was peace for the whole world. In 1956 he was given the International Peace Prize.', '说明·人物·画家齐白石', 172, '[{"q":"Besides painting, what else is Qi Baishi famous for?","answer":"A","options":["His seal carvings and poems.","His oil paintings of cities.","His large stone statues.","His songs and music."],"explanation":"原文提到他也以印章雕刻和诗歌闻名,转述。"},{"q":"Why did Qi leave some parts of his paintings blank at first?","answer":"B","options":["Because he had run out of ink.","He wanted to complete the small details while he could still see clearly, with flowers to come afterwards.","Because he disliked painting flowers.","Because the paper was too small."],"explanation":"原文说他想趁视力好时画细节,打算以后补上花朵,转述。"},{"q":"What did Qi do differently from many other old artists?","answer":"A","options":["Rather than retiring, he accepted greater social responsibility.","He stopped painting completely.","He left China to live abroad.","He refused to set any new goals."],"explanation":"原文对比:别的艺术家年老退隐,他却承担更多社会责任,转述。"}]'::jsonb, '[{"word":"stroke","cn":"笔触"},{"word":"blank","cn":"空白的"},{"word":"pursue","cn":"追求"}]'::jsonb, 2, 'required3', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Lonely World of Van Gogh', 'Vincent van Gogh was a Dutch painter who lived a poor and unhappy life. People who knew him often described him as a difficult person to get along with, and he was rarely cheerful. He was never able to sell his own paintings, and he depended on his brother for money. Yet his short life produced some of the most loved pictures in the world. His painting style is very personal: he used very bright colours, and the shapes in his works look strange and dreamlike. Night was a special subject for him. In his famous Starry Night, a quiet town sits under a sky full of shining stars, and a dark tree seems to join the earth with the sky. For Van Gogh, the night was often a time of safety, comfort and creativity. He died young and almost unknown, but after his death his paintings became some of the most valuable in the world. They have inspired songs, books and even a film told entirely through oil paintings.', '记叙·人物·梵高', 170, '[{"q":"How did people who knew Van Gogh usually describe him?","answer":"B","options":["As a cheerful and easy-going man.","As someone who was difficult company and seldom cheerful.","As a rich and popular painter.","As a calm and gentle teacher."],"explanation":"原文说他难相处、很少开心,转述。"},{"q":"What does the passage say about Starry Night?","answer":"C","options":["It shows a busy city in bright daylight.","It pictures the sea during a storm.","A peaceful village rests beneath a star-filled night sky.","It has no stars or sky at all."],"explanation":"原文描述安静小镇在繁星天空下,转述。"},{"q":"What happened to Van Gogh''s paintings after he died?","answer":"D","options":["They were all lost or destroyed.","They were sold cheaply and forgotten.","They stayed hidden in his brother''s house.","They grew into some of the world''s most highly valued works."],"explanation":"原文说他死后画作成为世上最珍贵的作品之一,转述。"}]'::jsonb, '[{"word":"creativity","cn":"创造力"},{"word":"inspiration","cn":"灵感"},{"word":"feature","cn":"(电影)正片"}]'::jsonb, 2, 'required3', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'When a Songwriter Won a Literature Prize', 'In 2016, the American singer and songwriter Bob Dylan was given the Nobel Prize for Literature. He became the first songwriter ever to receive this honour, and the news surprised the whole world. Dylan said that winning the prize was something he could never have imagined; he joked that he had about the same chance of standing on the moon. From an early age he had loved the works of the great writers, whose books were spoken of in respectful tones in classrooms. To find that his own name now joined theirs felt to him beyond words. When he started writing songs as a teenager, he only hoped they might be heard in small coffee houses or bars. Over the years he made dozens of records and played thousands of concerts around the world. Like Shakespeare, he said, he was often busy with both his creations and many ordinary matters, such as choosing the right musicians or the right studio. He was deeply grateful that his songs had found a place in the lives of so many people.', '议论·音乐·鲍勃·迪伦', 178, '[{"q":"Why was Dylan''s prize so surprising to many people?","answer":"A","options":["He was a songwriter, not a traditional writer of books.","He had never written any songs before.","He had refused the prize many times.","He was already too old to perform."],"explanation":"原文说他是首位获文学奖的词曲作者,故令人意外,转述。"},{"q":"What did Dylan hope for his songs when he was a teenager?","answer":"B","options":["That they would win a prize one day.","That a few people might hear them in small cafes or bars.","That they would be taught in every school.","That they would never be recorded."],"explanation":"原文说他少年时只希望歌曲能在小咖啡馆或酒吧被听到,转述。"},{"q":"Why does the writer compare Dylan with Shakespeare?","answer":"C","options":["Both wrote only plays for the theatre.","Both lived in the same century.","Both were busy with creation and many ordinary matters.","Both refused to perform in public."],"explanation":"原文说他像莎士比亚一样忙于创作与琐事,转述。"}]'::jsonb, '[{"word":"literature","cn":"文学"},{"word":"grateful","cn":"感激的"},{"word":"studio","cn":"录音室"}]'::jsonb, 2, 'required3', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Art of Chinese Ink Painting', 'Chinese ink painting is one of the oldest art forms in the world, and it looks very different from Western oil painting. Instead of filling the whole picture with colour, an ink painter often leaves large areas of the paper blank. These empty spaces are not mistakes; they let the viewer imagine water, sky or mist, and they give the picture a calm, open feeling. A good painter must control the brush with care, since a single stroke cannot be changed once it touches the soft paper. Painters use brushes of different sizes to create different effects, from thin gentle lines to thick energetic ones. Light and heavy ink are mixed to show near and far, light and shadow. The subjects are usually simple: a few fish, a branch of plum blossom, or a lonely mountain. Yet through these simple subjects, the artist tries to convey deep feelings about nature and life. To understand such a painting, a viewer should slow down and feel the spirit behind the simple shapes, rather than only count the objects on the paper.', '说明·技法·水墨画', 179, '[{"q":"Why does an ink painter often leave parts of the paper empty?","answer":"D","options":["Because there is not enough ink to use.","Because the rules forbid using colour.","Because empty paper is cheaper.","So that viewers can imagine things like water or sky."],"explanation":"原文说留白让观者想象水、天等,转述。"},{"q":"What must a painter be careful about when using the brush?","answer":"A","options":["Once a line meets the paper, it can no longer be altered.","The brush must always stay completely dry.","Only one colour may be used in a picture.","The paper must be painted from the corners first."],"explanation":"原文说一笔触纸便无法更改,转述。"},{"q":"How does the writer suggest viewing an ink painting?","answer":"B","options":["Count every object as quickly as possible.","Take it slowly and sense the feeling that the plain forms carry.","Look only at the brightest colours.","Compare it with Western oil paintings."],"explanation":"原文建议慢下来感受简单形状背后的精神,转述。"}]'::jsonb, '[{"word":"ink","cn":"墨"},{"word":"blank","cn":"空白的"},{"word":"convey","cn":"传达"}]'::jsonb, 2, 'required3', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'How to Read a Painting', 'Many people stand in front of a famous painting and feel they have nothing to say. They worry that art is only for experts. In fact, anyone can learn to enjoy a work of art. It does take a little knowledge, but the easiest way to begin is to place the work in its own time and place. We need to know how a painting is related to the world in which it was created, because every artist answers the questions of his or her age. Next, we should be able to say why we like or dislike a piece, instead of only repeating what others think. Not every work will attract you at first sight, and that is fine. Spend some time looking for signs of the feelings the artist wanted to share, such as joy, sadness or hope. One important thing to remember is that, in art appreciation, there is often no simple right or wrong answer. You may even notice something about a painting that no one else has ever thought about, and that small discovery is part of the pleasure of art.', '说明·方法·艺术欣赏', 186, '[{"q":"What does the writer say is the easiest way to begin enjoying art?","answer":"C","options":["Memorising the names of all famous painters.","Buying an expensive guidebook.","Setting the piece against the period and setting it came from.","Asking an expert to explain everything."],"explanation":"原文说最容易的起点是把作品放在它的时代与地点中,转述。"},{"q":"According to the passage, what should viewers be able to do?","answer":"D","options":["Agree with whatever experts say.","Like every famous painting equally.","Avoid talking about their feelings.","Give their own reasons for enjoying or disliking a work."],"explanation":"原文说要能说出自己喜欢或不喜欢的原因,转述。"},{"q":"What point does the writer make about right and wrong in art?","answer":"A","options":["A clear correct or incorrect response usually does not exist.","Only experts can give the correct answer.","Every painting has one clear meaning.","Beginners are always wrong about art."],"explanation":"原文说艺术欣赏常无简单对错,转述。"}]'::jsonb, '[{"word":"appreciate","cn":"欣赏"},{"word":"expression","cn":"表达"},{"word":"convey","cn":"传达"}]'::jsonb, 2, 'required3', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'A Field Trip to the Art Museum', 'Last Saturday our class took a field trip to the city art museum, and it turned out to be a wonderful day. Before the trip, our teacher asked us to check the museum''s website to discover which artworks were on display. We then decided where to go, when to go and whom to go with. When we arrived, a friendly guide led us through several quiet rooms full of paintings, carvings and old photographs. My favourite work was a large ink painting of a river, in which a tiny boat seemed almost lost among the mountains. The guide told us to look closely at the energetic strokes and the wide blank spaces, and slowly the river seemed to come alive. We were not allowed to touch any of the works, but we could take notes and a few pictures. Before we left, each of us bought a small postcard to bring home. Back in class, we wrote a short report about what we had discovered and shared our favourite artworks. Everyone agreed that seeing art in person is very different from looking at it in a book.', '记叙·活动·参观艺术馆', 187, '[{"q":"What did the students do before the trip?","answer":"B","options":["They painted their own pictures at home.","They checked the museum''s website to see which works were shown.","They bought tickets for a concert.","They wrote the report in advance."],"explanation":"原文说出发前老师让他们查网站看展出作品,转述。"},{"q":"What was the writer''s favourite artwork?","answer":"C","options":["A bright oil painting of a city street.","A stone statue of an artist.","A big river scene in ink showing one small boat.","An old black-and-white photograph."],"explanation":"原文说最喜欢一幅有小船的大幅水墨河景,转述。"},{"q":"What did everyone agree about at the end of the trip?","answer":"D","options":["Books are always better than real museums.","Touching the paintings is the best way to learn.","The museum was too crowded to enjoy.","Viewing artworks for real feels quite unlike studying them in print."],"explanation":"原文结尾说亲眼看艺术与在书上看很不同,转述。"}]'::jsonb, '[{"word":"display","cn":"陈列;展出"},{"word":"stroke","cn":"笔触"},{"word":"blank","cn":"空白的"}]'::jsonb, 2, 'required3', 'U2', 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U2', 'My First Calligraphy Lesson', 'On Saturday morning I went to my first Chinese calligraphy lesson. At first the brush felt strange in my hand, and my lines were thin and (1)____. My teacher, an old man with kind eyes, told me not to (2)____ up so easily. He said that every great artist had to (3)____ for years before the brush would obey him. He showed me how to hold the brush and how to control each (4)____ on the soft paper. "Do not try to fill the whole page," he said. "A little (5)____ space can make the work more beautiful." I watched him paint a single bamboo leaf in a fresh and lively (6)____. It looked so simple, yet it was full of (7)____. When I tried again, my hand was steadier, and I began to (8)____ how hard this art really was. By the end of the lesson I was tired but (9)____, because I had learned something new and old at the same time. I decided (10)____ back every week.', 170, 2, '[{"q":"1","answer":"A","options":["weak","loud","sweet","cold"],"explanation":"线条又细又「弱」(weak),与 thin 并列。"},{"q":"2","answer":"B","options":["wake","give","look","stand"],"explanation":"give up 放弃,固定短语。"},{"q":"3","answer":"C","options":["sleep","shout","practise","travel"],"explanation":"练习 practise 多年才能掌握。"},{"q":"4","answer":"D","options":["price","noise","meal","stroke"],"explanation":"控制纸上的每一「笔触」(stroke)。"},{"q":"5","answer":"A","options":["blank","dark","busy","wet"],"explanation":"blank space 留白。"},{"q":"6","answer":"B","options":["price","manner","season","machine"],"explanation":"in a ... manner 以……方式;呼应课文 fresh and lively manner。"},{"q":"7","answer":"C","options":["money","danger","feeling","noise"],"explanation":"充满「情感」(feeling)。"},{"q":"8","answer":"D","options":["forget","refuse","sell","appreciate"],"explanation":"appreciate 领会、体会这门艺术之难。"},{"q":"9","answer":"A","options":["happy","angry","afraid","bored"],"explanation":"学到新东西,因而「高兴」(happy)。"},{"q":"10","answer":"B","options":["coming","to come","come","came"],"explanation":"decide to do,不定式作宾语(呼应本单元语法)。"}]'::jsonb, 1, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U2', 'A Visit to the Painter''s Studio', 'Our art club was lucky enough to visit a famous painter''s (1)____ last week. The room was filled with brushes, bottles of ink and half-finished pictures. The painter welcomed us with a warm (2)____ and asked us to sit down. He was (3)____ even in his seventies, and his eyes were still bright. He told us that he wanted (4)____ his love of nature through simple shapes. While we watched, he picked up a brush and, with a few (5)____ strokes, turned a blank sheet into a lively fish. We could hardly (6)____ how quickly it had happened. He explained that a good painter must (7)____ the brush with great care, because a single line cannot be changed. One student asked what (8)____ he hoped to send through his art. "Peace and joy," he answered with a gentle smile. Before we left, he encouraged each of us (9)____ our own style instead of copying others. We thanked him and walked home, (10)____ for such a wonderful afternoon.', 167, 2, '[{"q":"1","answer":"C","options":["garden","kitchen","studio","station"],"explanation":"画家的「工作室」(studio)。"},{"q":"2","answer":"D","options":["ticket","price","weather","greeting"],"explanation":"热情的「问候」(greeting)。"},{"q":"3","answer":"A","options":["energetic","lazy","silent","tired"],"explanation":"七十多岁仍「精力充沛」(energetic)。"},{"q":"4","answer":"B","options":["conveying","to convey","convey","conveyed"],"explanation":"want to do,不定式作宾语。"},{"q":"5","answer":"C","options":["empty","quiet","energetic","cheap"],"explanation":"充满活力的「笔触」(energetic strokes)。"},{"q":"6","answer":"D","options":["drink","wash","buy","believe"],"explanation":"几乎不敢「相信」(believe)。"},{"q":"7","answer":"A","options":["control","throw","lose","break"],"explanation":"必须小心「控制」(control)画笔。"},{"q":"8","answer":"B","options":["price","message","season","machine"],"explanation":"想通过艺术传达什么「信息」(message)。"},{"q":"9","answer":"C","options":["developing","develop","to develop","developed"],"explanation":"encourage sb to do,补足语带 to。"},{"q":"10","answer":"D","options":["angry","afraid","sorry","grateful"],"explanation":"为美好的下午而「感激」(grateful)。"}]'::jsonb, 2, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U2', 'The Story Behind a Song', 'When the famous singer was young, he never (1)____ that one day he would win a great prize. As a teenager he only hoped his songs might be (2)____ in small coffee houses. He wrote about peace, freedom and the lives of (3)____ people. His music slowly reached a much bigger (4)____, and he made dozens of records. Years later, he was (5)____ a famous prize for literature, which surprised the whole world. He said he was deeply (6)____ that his songs had found a place in so many hearts. In his speech he (7)____ his warmest greetings to all the guests. He also remembered the great writers whose works were spoken of in (8)____ tones at school. Like them, he said, he was often (9)____ with both his art and ordinary daily matters. "Some things never change," he added, "even after four hundred years." The (10)____ rose to their feet and cheered for a long time.', 157, 2, '[{"q":"1","answer":"A","options":["imagined","cooked","washed","counted"],"explanation":"从未「想象」(imagined)会获奖。"},{"q":"2","answer":"B","options":["sold","heard","eaten","lost"],"explanation":"希望歌曲能被「听到」(heard)。"},{"q":"3","answer":"C","options":["foreign","ancient","ordinary","empty"],"explanation":"「普通」(ordinary)人的生活。"},{"q":"4","answer":"D","options":["garden","machine","river","audience"],"explanation":"触及更大的「听众」(audience)。"},{"q":"5","answer":"A","options":["awarded","sold","cooked","carried"],"explanation":"be awarded a prize 被授予奖项。"},{"q":"6","answer":"B","options":["angry","grateful","afraid","sorry"],"explanation":"深深「感激」(grateful)。"},{"q":"7","answer":"C","options":["closed","dropped","extended","broke"],"explanation":"extend greetings 致以问候。"},{"q":"8","answer":"D","options":["noisy","empty","cheap","respectful"],"explanation":"以「充满敬意」(respectful)的语气谈论。"},{"q":"9","answer":"A","options":["occupied","filled","covered","painted"],"explanation":"be occupied with 忙于(固定搭配)。"},{"q":"10","answer":"B","options":["weather","audience","machine","season"],"explanation":"「观众」(audience)起立欢呼。"}]'::jsonb, 3, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U2', 'Painting My Grandmother', 'For the school art show, I decided to paint a (1)____ of my grandmother. I wanted the picture to (2)____ how kind and patient she is. First I asked her to sit quietly by the window so that I could see every (3)____ of her face. The soft afternoon light made her grey hair (4)____ almost silver. I worked slowly, adding line after line, because I knew a single wrong (5)____ could ruin the whole picture. It was not easy, and at times I almost wanted to (6)____ up. But I kept telling myself to focus on the small (7)____, just as the great masters did. After three afternoons, the (8)____ was finally finished. When my grandmother saw it, her eyes filled with tears, and she was so (9)____ that she hugged me at once. The teacher later chose my work to be put (10)____ display in the school hall. I felt proud that art had helped me show my love.', 161, 2, '[{"q":"1","answer":"C","options":["ticket","machine","portrait","garden"],"explanation":"画一幅「肖像」(portrait)。"},{"q":"2","answer":"D","options":["sell","wash","count","show"],"explanation":"想让画「展现」(show)祖母的善良。"},{"q":"3","answer":"A","options":["detail","price","noise","season"],"explanation":"看清脸上每一「细节」(detail)。"},{"q":"4","answer":"B","options":["smell","look","taste","sound"],"explanation":"让头发「看起来」(look)像银色,系动词。"},{"q":"5","answer":"C","options":["meal","price","stroke","song"],"explanation":"一处错误的「笔触」(stroke)。"},{"q":"6","answer":"D","options":["stand","wake","look","give"],"explanation":"give up 放弃。"},{"q":"7","answer":"A","options":["details","prices","noises","meals"],"explanation":"专注于小「细节」(details)。"},{"q":"8","answer":"B","options":["kitchen","painting","garden","station"],"explanation":"「画作」(painting)终于完成。"},{"q":"9","answer":"C","options":["bored","afraid","grateful","angry"],"explanation":"祖母如此「感激」(grateful)以至于拥抱我。"},{"q":"10","answer":"D","options":["off","out","down","on"],"explanation":"on display 陈列、展出(固定短语)。"}]'::jsonb, 4, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U2', 'An Afternoon Art Class', 'Our new art teacher, Miss Lin, has changed the way I see the world. On the first day she did not let us (1)____ at once. Instead, she made us close our eyes and (2)____ a happy moment. "Art begins with feeling," she said. Then she asked each of us to (3)____ that feeling on paper using only three colours. At first I had no idea what (4)____ paint, so I just made a few simple shapes. Miss Lin walked over, looked at my work, and (5)____ me to add more energetic lines. Slowly my page began to come (6)____. She told us that the easiest way to enjoy art is to (7)____ a work in its own time and place. She also said there is often no clear right or (8)____ answer in art. By the end of the class, the walls were (9)____ with bright pictures, and everyone wanted (10)____ them to friends. I had never enjoyed a lesson so much.', 163, 2, '[{"q":"1","answer":"A","options":["paint","sleep","shout","eat"],"explanation":"不让我们马上「画画」(paint)。"},{"q":"2","answer":"B","options":["wash","imagine","buy","count"],"explanation":"闭眼「想象」(imagine)一个快乐时刻。"},{"q":"3","answer":"C","options":["sell","throw","convey","lose"],"explanation":"用颜色「传达」(convey)那种感觉。"},{"q":"4","answer":"D","options":["of","in","with","to"],"explanation":"what to paint 疑问词+to do(呼应本单元语法)。"},{"q":"5","answer":"A","options":["encouraged","stopped","forced","warned"],"explanation":"encourage sb to do,鼓励我加更多线条。"},{"q":"6","answer":"B","options":["asleep","alive","apart","down"],"explanation":"画面渐渐「活」(come alive)起来。"},{"q":"7","answer":"C","options":["drop","break","place","sell"],"explanation":"place a work in its time and place,把作品放在它的时空中。"},{"q":"8","answer":"D","options":["early","cheap","quiet","wrong"],"explanation":"right or wrong 对或错,固定搭配。"},{"q":"9","answer":"A","options":["covered","emptied","cleaned","opened"],"explanation":"墙上「挂满」(be covered with)明亮的画。"},{"q":"10","answer":"B","options":["showing","to show","show","showed"],"explanation":"want to do,不定式作宾语。"}]'::jsonb, 5, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U2', 'The Young Sculptor', 'Lin Tao was only sixteen, but everyone in town already (1)____ him as a gifted young artist. While other children played outside, he spent hours shaping wet clay with his hands. His dream was (2)____ a beautiful statue for the city park. The work was slow and difficult, and a single mistake could (3)____ days of effort. Yet Lin Tao refused (4)____ up. He studied the faces of ordinary people, trying to catch every (5)____ in their expressions. "A good statue should (6)____ real feeling," he often said. One evening a famous artist visited his small workshop and was (7)____ by what he saw. The man encouraged Lin Tao (8)____ his work to a national art show. To everyone''s joy, the young sculptor won first prize, and his statue was put on (9)____ in the city museum. Standing beside his work, Lin Tao felt deeply (10)____ for all the help he had received along the way.', 156, 2, '[{"q":"1","answer":"C","options":["washed","sold","recognised","counted"],"explanation":"大家「认可」(recognised)他是有天赋的艺术家。"},{"q":"2","answer":"D","options":["making","make","made","to make"],"explanation":"His dream was to do,不定式作表语。"},{"q":"3","answer":"A","options":["waste","save","wash","buy"],"explanation":"一个错误会「浪费」(waste)多日努力。"},{"q":"4","answer":"B","options":["giving","to give","give","gave"],"explanation":"refuse to do,不定式作宾语。"},{"q":"5","answer":"C","options":["price","noise","detail","meal"],"explanation":"捕捉表情中的每个「细节」(detail)。"},{"q":"6","answer":"D","options":["sell","wash","lose","convey"],"explanation":"好的雕像应「传达」(convey)真实情感。"},{"q":"7","answer":"A","options":["amazed","bored","frightened","tired"],"explanation":"被所见「惊叹」(amazed)。"},{"q":"8","answer":"B","options":["sending","to send","send","sent"],"explanation":"encourage sb to do,补足语带 to。"},{"q":"9","answer":"C","options":["sale","fire","display","paper"],"explanation":"on display 陈列、展出(固定短语)。"},{"q":"10","answer":"D","options":["angry","afraid","bored","grateful"],"explanation":"对一路的帮助深深「感激」(grateful)。"}]'::jsonb, 6, 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·对话 Planning a Museum Visit', '上外版必修第三册 U2 · dialogue', 3, 'Mia: Hi, Leo. Are you free this Saturday? I really want to visit the new art museum.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·短文 Van Gogh in a Few Minutes', '上外版必修第三册 U2 · passage', 2, 'Welcome to today''s short talk about Vincent van Gogh. He was a Dutch painter who lived a poor and rather unhappy life. People who knew him said he was hard to get along with, and he was rarely cheerful. During his life he was never able to sell his own paintings, so he depended on his brother for money. Yet today his works are among the most loved in the world. His painting style is very personal: he used very bright colours, and the shapes in his pictures look strange and dreamlike. After his death, his paintings became some of the most valuable on Earth, and they have inspired many songs and films.', '今天的短讲介绍梵高:他是一位荷兰画家,生活贫困、并不快乐;认识他的人说他难相处、很少开心;在世时他从未能卖出自己的画,靠弟弟接济;然而如今他的作品是世上最受喜爱的;他画风很个人化,用极明亮的色彩,形状奇异如梦;他死后画作成为世上最珍贵的作品之一,启发了许多歌曲和电影。', 'uk_female', '[{"q":"What was Van Gogh''s nationality?","type":"choice","answer":"D","options":["French.","American.","British.","Dutch."]},{"q":"How did people who knew him describe him?","type":"choice","answer":"A","options":["Hard to get along with and rarely cheerful.","Friendly and always happy.","Rich and famous.","Calm and gentle."]},{"q":"How did he get money during his life?","type":"choice","answer":"B","options":["He sold many paintings.","He depended on his brother.","He worked in a bank.","He won several prizes."]},{"q":"What is special about his painting style?","type":"choice","answer":"C","options":["Only black and white lines.","Very dark and simple shapes.","Very bright colours and dreamlike shapes.","Photographs of real people."]},{"q":"What happened to his paintings after he died?","type":"choice","answer":"D","options":["They were all destroyed.","They were given away for free.","They were forgotten completely.","They became some of the most valuable in the world."]}]'::jsonb, '[]'::jsonb, 'short', 'required3', 'U2', 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·对话 The School Art Festival', '上外版必修第三册 U2 · dialogue', 3, 'Tom: Hi, Sophie. Are you taking part in the School Art Festival next week?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·短文 The People''s Artist', '上外版必修第三册 U2 · passage', 2, 'Let me tell you about a great Chinese painter named Qi Baishi. He painted landscapes, birds, flowers and small figures, and his works are full of feeling. Using heavy ink and energetic strokes, he created pictures in a fresh and lively manner. Even in his seventies he stayed hardworking, often painting tiny insects in fine detail. As he grew older, he took on more social duties instead of retiring. He once said that what he truly pursued was peace for the whole world. In 1956 he was awarded the International Peace Prize, and people lovingly called him the People''s Artist.', '介绍中国画家齐白石:他画山水、鸟、花和小人物,作品饱含情感;用浓墨和充满活力的笔触,以清新生动的方式作画;七十多岁仍勤奋,常细致地画小昆虫;年纪渐长却承担更多社会责任而非退隐;他说自己真正追求的是世界和平;1956年获国际和平奖,人们亲切地称他为「人民艺术家」。', 'uk_female', '[{"q":"What kinds of things did Qi Baishi paint?","type":"choice","answer":"B","options":["Only modern buildings.","Landscapes, birds, flowers and small figures.","Only cars and machines.","Only the sea and ships."]},{"q":"How are his works described?","type":"choice","answer":"C","options":["Dark and cold.","Empty and boring.","Fresh and lively, full of feeling.","Strange and frightening."]},{"q":"What did he do as he grew older?","type":"choice","answer":"D","options":["He stopped painting.","He moved to another country.","He sold all his works.","He took on more social duties."]},{"q":"What did Qi Baishi say he truly pursued?","type":"choice","answer":"A","options":["Peace for the whole world.","Money and fame.","A big house.","A quiet life alone."]},{"q":"What prize was he given in 1956?","type":"choice","answer":"B","options":["The Nobel Prize for Literature.","The International Peace Prize.","A music award.","A science prize."]}]'::jsonb, '[]'::jsonb, 'short', 'required3', 'U2', 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·对话 Learning the Guitar', '上外版必修第三册 U2 · dialogue', 3, 'Ben: Emma, I''ve decided to learn to play the guitar this year.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·短文 How to Enjoy a Painting', '上外版必修第三册 U2 · passage', 2, 'Here is a simple tip for anyone who feels nervous in front of a famous painting. You do not need to be an expert to enjoy art. The easiest way to begin is to place the work in its own time and place, and to think about the world in which it was created. Next, ask yourself why you like or dislike it, instead of only repeating what others say. Not every picture will attract you at first sight, and that is fine. Take your time to look for the feelings the artist wanted to share. Remember, in art there is often no simple right or wrong answer.', '给在名画前紧张的人一个小建议:欣赏艺术无需做专家;最容易的起点是把作品放在它的时代与地点中,想想它诞生的世界;接着问自己为何喜欢或不喜欢,而不是只重复别人的话;不是每幅画都会一见钟情,这很正常;慢慢寻找艺术家想分享的情感;记住,艺术中往往没有简单的对错答案。', 'uk_female', '[{"q":"According to the talk, who can enjoy art?","type":"choice","answer":"D","options":["Only painters.","Only rich people.","Only museum guides.","Anyone, not only experts."]},{"q":"What is the easiest way to begin enjoying a painting?","type":"choice","answer":"A","options":["Place the work in its own time and place.","Buy the most expensive ticket.","Touch the painting gently.","Copy what experts say."]},{"q":"What should you ask yourself about a work?","type":"choice","answer":"B","options":["How much it costs.","Why you like or dislike it.","Who painted it first.","When the museum closes."]},{"q":"What should you do if a picture does not attract you at first?","type":"choice","answer":"C","options":["Leave the museum at once.","Decide it is a bad work.","Take your time and keep looking.","Ask for your money back."]},{"q":"What does the speaker say about right and wrong in art?","type":"choice","answer":"D","options":["There is always one correct answer.","Only experts know the answer.","Beginners are always wrong.","There is often no simple right or wrong answer."]}]'::jsonb, '[]'::jsonb, 'short', 'required3', 'U2', 'sufe');
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Introducing an Artist for an Art Exhibition(为艺术展介绍一位艺术家)', 'Introducing an Artist', '学校艺术节将举办一场艺术展。请你用英语为齐白石写一段约80-100词的介绍,放在展品旁。要求用「总—分」结构:① 先写一句总述(他是谁、地位如何);② 再用细节支撑:他的作品形式与题材、艺术风格、传达的信息/象征意义、所获荣誉与社会影响。注意行文连贯、句句围绕中心。', 'The School Art Festival will hold an art exhibition. Write an introduction (about 80-100 words) to the painter Qi Baishi to be placed beside his works. Use the general-specific pattern: 1) begin with a general statement (who he is and his place in art); 2) support it with details — his art forms and subjects, his artistic style, the messages or symbolic meanings he conveys, and his honours and social influence.', '["总述句:Qi Baishi is one of the best-known Chinese painters of the 20th century.","作品与题材:art forms (paintings, seal carvings, poems) + subjects (shrimps, flowers, doves)","风格与信息:fresh and lively style, heavy ink and energetic strokes; conveys love of nature and a wish for peace","荣誉与影响:awarded the International Peace Prize; called the People''s Artist"]'::jsonb, 70, 100, 'Qi Baishi is one of the best-known Chinese painters of the twentieth century. He worked in several art forms, creating paintings, seal carvings and poems. His favourite subjects were everyday things such as shrimps, flowers and doves. Using heavy ink and energetic strokes, he painted in a fresh and lively manner. Through these simple subjects he conveyed his deep love of nature and his wish for a peaceful world. Honoured as the People''s Artist and awarded the International Peace Prize, he has inspired countless artists and is loved by ordinary people across the country.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["Qi Baishi is one of the best-known Chinese painters of the twentieth century.","Using heavy ink and energetic strokes, he painted in a fresh and lively manner.","Through these simple subjects he conveyed his deep love of nature and his wish for peace.","Honoured as the People''s Artist, he has inspired countless artists across the country."]'::jsonb, '[{"wrong":"He is good at to paint flowers.","correct":"He is good at painting flowers.","note":"be good at + doing,介词 at 后用动名词。"},{"wrong":"His works conveys a love of nature.","correct":"His works convey a love of nature.","note":"主语 works 是复数,动词不加 s。"},{"wrong":"He was awarded with the Peace Prize.","correct":"He was awarded the Peace Prize.","note":"award sb sth,被动 be awarded sth,不加 with。"}]'::jsonb, '【介绍艺术家·总—分结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required3', 'U2', '{"title":"不定式 to do 作宾语 / 宾补 / 状语 / 定语 速查","intro":"不定式 to do 在句中能当宾语、宾语补足语、状语和定语。判断口诀:看它跟在谁后面、补充说明谁、或修饰前面哪个名词。特别小心使役/感官动词后宾补「不带 to」。","table":{"headers":["用法","结构 / 例句"],"rows":[["作宾语","want/decide/hope/plan/refuse/manage + to do:He decided to focus on the details."],["疑问词+to do(宾语)","know/wonder/decide + how/what/where/whether to do:She wondered how to dress."],["作宾补(带to)","ask/tell/want/allow/encourage sb to do:The teacher advised me to go."],["作宾补(不带to)","make/let/have + sb do;hear/watch/feel/see sb do:I heard him sing."],["作状语","(in order)/(so as) to do 表目的;…only to do 表结果:Painters use brushes to create effects."],["作定语","the first/best + to do;a way/time/chance to do;sth to do:the first songwriter to win it."]]},"specialRules":[{"rule":"使役动词 make / let / have 后,宾补用动词原形(不带 to)","mark":"make sb do √ / make sb to do ×"},{"rule":"感官动词 hear / watch / feel / see 后,宾补也用原形(不带 to)","mark":"I watched her paint √"},{"rule":"make/hear 等变被动后,to 要还原","mark":"He was made to wait.(主动 make sb do → 被动 be made to do)"},{"rule":"序数词、形容词最高级、the only/last 后常用 to do 作定语","mark":"the first/best/only … to do"}],"why":["不定式表示「将要、目的或一次性的动作」,所以在「打算做/为了做/要去做的事物」这些场合自然出现;而使役/感官动词本身已含动作意味,后面只需原形动词补充宾语在做什么,故省去 to。"],"gaokaoPoints":["to do 与 doing 的区分(decide to do vs enjoy doing);疑问词+to do 高频。","make/let/have/hear/watch + sb do 的「不带 to」考点;变被动时 to 回来。","the first/best/only + to do、a way/chance to do 作定语,语法填空常考。"],"examVsReal":[{"exam":"I heard him sing a song.(考试:hear sb do)","real":"I heard him singing a song.","note":"考试爱考原形 do(听到全过程);真实口语里 doing 表示「听到正在唱」,两者侧重不同。"},{"exam":"the first person to do it（考试用 to do 定语）","real":"the first person who did it","note":"考试偏好不定式定语;口语常用定语从句,意思相同。"}]}'::jsonb, 'sufe');
